import {SCENARIOS,scenarioFor,scenarioCase} from './mission-scenarios.js';
import {initialMission,snapshot,availability,forecast,commitChoice,emergencyHandover,frameAt,missionOutcome,reviewArgument,LIMITS,RESOURCE_NAMES} from './mission-engine.js';
import {playbackControls,advancePlayback} from './mission-playback.js';
import {flightNarrative} from './mission-direction.js';
import {createMissionScene} from './mission-scene.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const units={battery:'%',thermalMargin:'°C',deltaV:'m/s',operatorMinutes:'min'};
export function renderMission(){return `<div class="mission-heading"><div><span class="eyebrow">ORBITAL ATLAS / INTERACTIVE FLIGHT DECK</span><h1>Take the flight director’s seat.</h1><p>One spacecraft. One orbit. Every decision leaves a trace.</p></div><div class="mission-heading-actions"><button class="button subtle" id="mission-expand" aria-pressed="false">⛶ Expand flight deck</button><button class="text-button" id="mission-export">Export mission ↓</button></div></div><div id="mission-root" class="mission-deck"></div>`}
export function mountMission(baseCase,saved,onSave,notify){
 let c=scenarioCase(baseCase,saved?.scenarioId);let nextScenario=c.scenario.id;
 const $=s=>document.querySelector(s);let state=saved?.schema===2&&saved.caseId==='atlas-r8.1'?saved:initialMission(c),selected=null,scene=null,replay=state.time,playing=false,raf,last=0,disposed=false,review=null,tab='decision',speed=1,controlKey='',consoleKey='',view='orbit',demo=false,demoSaved=null,demoHold=0;let root=$('#mission-root');
 document.body.classList.add('mission-page');
 const persist=()=>{if(!demo)onSave(state)};const mood=()=>state.ended?(missionOutcome(state).kind==='success'?'pleased':'alert'):state.flags.includes('releaseHeld')||state.battery<45||state.thermalMargin<7?'alert':'thinking';
 function guide(){if(selected){let f=forecast(c,state,selected);return f.reason||f.choice.coaching}if(state.ended){let o=missionOutcome(state);return o.kind==='success'?'You earned a narrow continuation. Now trace your recommendation to the records and resources that actually support it.':o.kind==='hold'?'A hold is a defensible outcome. Explain what you preserved, which gap prevented continuation, and who owns the next action.':'The mission ended with an assurance gap. Keep that gap visible in your recommendation; the outcome is not a complete pass.'}if(state.history.length){let lastDecision=state.history.at(-1),arrived=state.events.filter(e=>e.time>lastDecision.time);return arrived.length?arrived.map(e=>e.text).join(' ')+' Your next decision uses this updated record.':lastDecision.coaching}return c.scenario.lesson+' I’m ORI. You control one candidate spacecraft, not all 84. Select a decision to inspect its resource cost, then commit and watch the consequences unfold.'}
 function metrics(){return Object.entries(RESOURCE_NAMES).map(([k,n])=>`<div class="deck-metric"><div><span>${n}</span><small>${units[k]}</small></div><strong id="mm-${k}">${state[k].toFixed(1)}</strong><div class="deck-meter"><i id="meter-${k}"></i><em style="left:${LIMITS[k]/c.initial[k]*100}%"></em></div><small>Floor ${LIMITS[k]} ${units[k]}</small><svg id="spark-${k}" viewBox="0 0 150 28" role="img" aria-label="${n} recorded trend"></svg></div>`).join('')}
 function render(){controlKey='';consoleKey='';scene?.dispose();root.innerHTML=`
 <header class="deck-header"><div class="deck-identity"><span class="live-dot"></span><b>ATLAS <em>/ 01</em></b><span>EARTH OBSERVATION · LEO</span></div><div class="deck-session"><span class="deck-training">${demo?'GUIDED DEMO':'TRAINING SIMULATION'}</span>${demo?'':'<button class="deck-link" data-start-demo>▷ Guided flight</button>'}<button class="deck-link" ${demo?'id="exit-demo"':'data-restart'}>${demo?'Exit demo ×':'Change scenario ↺'}</button></div></header>
 <section class="deck-briefing" aria-label="Scenario briefing"><div><span>ACTIVE SCENARIO</span><strong>${esc(c.scenario.name)}</strong></div><p>${esc(c.scenario.brief)}</p></section>
 <div class="deck-grid"><section class="deck-theater"><div class="deck-viewbar"><div class="deck-view-tabs" aria-label="Mission camera"><button data-vehicle="orbit" class="${view==='orbit'?'active':''}" aria-pressed="${view==='orbit'}">Orbital view</button><button data-vehicle="chase" class="${view==='chase'?'active':''}" aria-pressed="${view==='chase'}">Track spacecraft</button><button data-vehicle="link" class="${view==='link'?'active':''}" aria-pressed="${view==='link'}">Ground link</button></div><button id="explode-vehicle" aria-pressed="false" title="Inspect the spacecraft assembly">Inspect +</button></div>
 <div class="deck-scene" id="mission-visual"><div class="deck-scene-caption"><span id="scene-phase">SUNLIT OPERATIONS</span><h2 id="scene-headline">The orbit is yours.</h2><p id="scene-detail">Release the spacecraft into a bounded advisory trial.</p></div><div class="deck-clock"><span>MISSION ELAPSED</span><b id="scene-time">T+00:00</b><small id="mission-mode">AWAITING COMMAND</small></div><div class="scene-zoom" aria-label="Camera zoom"><button data-zoom="-0.25" aria-label="Zoom in">+</button><button data-zoom="0.25" aria-label="Zoom out">−</button><button id="camera-reset" aria-label="Reset camera">↺</button></div><div class="deck-scene-legend"><span><i></i> ATLAS–01</span><span><i></i> ECLIPSE ARC</span><span id="scene-context-tag">AUTHORED 96-MIN ORBIT</span></div></div>
 <div class="deck-transport"><button id="mission-play" class="deck-play">▶ Start mission</button><span id="mission-clock">0.0 / 96 min</span><label>Rate <select id="mission-speed" aria-label="Flight playback speed"><option value="1">1 min/s</option><option value="3">3 min/s</option><option value="6">6 min/s</option></select></label><button id="mission-live">Latest state ↗</button></div>
 <div class="deck-timeline"><div class="deck-timeline-labels"><span>RELEASE</span><span>ECLIPSE · T+32–62</span><span>HANDOVER</span></div><div class="deck-time-track"><span class="deck-eclipse-band"></span><span id="deck-time-fill"></span><input id="mission-time" type="range" min="0" max="96" value="${state.time}" step="0.1" aria-label="Replay mission time" ${state.time===0?'disabled':''}></div><div class="deck-milestones">${c.stages.map((st,i)=>`<button data-seek="${st.minute}" ${st.minute>state.time?'disabled':''} class="${i<state.stage?'passed':i===state.stage&&!state.ended?'current':''}"><b>${String(i+1).padStart(2,'0')}</b><span>${['Authority','Observation','Ground pass','Encounter','Release','Handover'][i]}</span><small>T+${st.minute}</small></button>`).join('')}</div></div>
 <section class="deck-metrics" aria-label="Mission resource budgets">${metrics()}</section></section>
 <aside class="deck-console" aria-label="Mission command console"><div class="deck-console-status"><span class="eyebrow" id="flight-status" role="status"></span><span id="decision-count">${state.history.length} / 6</span></div><div id="flight-work"></div><div class="ori-flight" id="ori-mission"><div class="ori-sprite ${mood()}" role="img" aria-label="ORI, your flight director"></div><div><span>ORI / FLIGHT DIRECTOR</span><p id="mission-coaching">${esc(guide())}</p></div></div></aside></div>
 <div class="deck-system-strip"><span><i id="contact-led"></i> GROUND <b id="mission-contact"></b></span><span>AUTHORITY <b>Advisory only</b></span><span>RELEASE <b id="mission-release"></b></span><span>DATA VALUE <b id="mission-data-value"></b><small> case units</small></span></div>
 <div class="deck-bottom"><p>Authored training case. Orbit path and spacecraft are enlarged for clarity; no live telemetry or flight authority.</p><div><button data-open-work="evidence">Evidence locker <b id="deck-evidence-count">${state.evidence.length}</b></button><button data-open-work="ledger">Decision ledger <b>${state.history.length}</b></button><button data-open-work="model">Model & sources ↗</button></div></div>
 <dialog id="mission-console" aria-label="Mission record"><div class="mission-console-head"><b>ATLAS / MISSION RECORD</b><button class="button subtle" id="close-mission-console" autofocus>Back to flight ×</button></div><nav class="mission-tabs" aria-label="Mission work areas"><button data-mission-tab="decision">${state.ended?'Debrief & argument':'Current decision'}</button><button data-mission-tab="evidence">Evidence locker</button><button data-mission-tab="ledger">Decision ledger</button><button data-mission-tab="model">Model & sources</button></nav><div id="mission-work"></div></dialog>
 <dialog id="restart-dialog"><span class="eyebrow">MISSION SELECTION</span><h3>Same orbit. Different pressures.</h3><p>Choose the conditions you want to practise. Your current resource totals will be kept for comparison.</p><div class="scenario-options">${SCENARIOS.map(s=>`<button data-scenario="${s.id}" class="scenario-option ${s.id===nextScenario?'selected':''}" aria-pressed="${s.id===nextScenario}"><small>${esc(s.tag)}</small><strong>${esc(s.name)}</strong><span>${esc(s.brief)}</span></button>`).join('')}</div><div class="filter-row"><button id="confirm-restart" class="button dark">Start new run</button><button id="cancel-restart" class="button subtle">Keep this run</button></div></dialog>`;
 $('#mission-speed').value=String(speed);renderFlight();scene=createMissionScene($('#mission-visual'),()=>({...frameAt(state,replay),playing,view}));scene.view(view);drawTrends();paintFrame();}
 function clock(t){return String(Math.floor(t)).padStart(2,'0')+':'+String(Math.floor(t%1*60)).padStart(2,'0')}
 function renderFlight(){const work=$('#flight-work');
 if(replay<state.time){let n=flightNarrative(frameAt(state,replay)),h=state.history.find(x=>replay>=x.time&&replay<x.to)||state.history.at(-1);work.innerHTML=`<div class="flight-transit"><span class="eyebrow">${demo?'ORI’S GUIDED FLIGHT':'COMMITTED / FLIGHT IN PROGRESS'}</span><h2>${esc(n.title)}</h2><p>${esc(n.detail)}</p><div class="flight-arrival"><span>${state.ended?'PLAYBACK END':'NEXT HOLD'}</span><strong>T+${state.time}</strong><p>${state.ended?'Integrated handover':esc(c.stages[state.stage].title)}</p></div><div class="flight-action-record"><span>LAST COMMITMENT</span><h3>${esc(h?.label)}</h3><p>${esc(h?.coaching)}</p></div><button class="deck-primary" id="mission-primary">${playing?'Ⅱ Pause flight':'▶ Resume flight'}</button><button class="deck-secondary" id="mission-open-decision">${state.ended?'Go to final debrief':'Skip to next decision'} →</button></div>`;work.scrollTop=0;return}
 if(state.ended){let o=missionOutcome(state);work.innerHTML=`<div class="flight-result"><span class="eyebrow">${demo?'GUIDED FLIGHT COMPLETE':'MISSION DEBRIEF'} · T+${state.time}</span><div class="result-orbit">${o.kind==='success'?'✓':'◇'}</div><h2>${o.title}</h2><p>${o.kind==='success'?'A narrow continuation, earned through current evidence and protected margins.':'Your record preserves the release boundary. Make the remaining obligations explicit.'}</p><div class="result-evidence"><b>${state.history.length}</b> decisions recorded <b>${state.evidence.length}</b> evidence records</div><button class="deck-primary" ${demo?'data-exit-demo':'id="mission-open-decision"'}>${demo?'Fly your own mission →':'Review & defend your outcome →'}</button><button class="deck-secondary" id="mission-primary">↻ Replay mission</button></div>`;return}
 let st=c.stages[state.stage];work.innerHTML=`<div class="flight-brief"><span class="eyebrow">DECISION ${state.stage+1} / 6 · T+${state.time}</span><h2>${esc(st.title)}</h2><p>${esc(st.brief)}</p></div>${demo?'<div class="demo-director">ORI is flying a reference path. Your saved mission is untouched.</div>':''}<div class="flight-choices">${st.choices.map((o,i)=>{let reason=availability(c,state,o);return `<button class="flight-choice ${selected===o.id?'selected':''} ${reason?'unavailable':''}" data-choice="${o.id}" aria-pressed="${selected===o.id}" ${reason?'aria-disabled="true"':''} ${demo?'disabled':''}><span>${String.fromCharCode(65+i)}</span><div><h3>${esc(o.title)}</h3><small>${reason?'⊘ '+esc(reason):Object.entries(o.effects).filter(([k])=>k in units).map(([k,v])=>`${v>0?'+':''}${v} ${units[k]} ${k==='operatorMinutes'?'attention':k==='thermalMargin'?'margin':k==='deltaV'?'reserve':'power'}`).join(' · ')||'No immediate resource cost'}</small></div><i>${reason?'⊘':selected===o.id?'✓':'↗'}</i></button>`}).join('')}</div><div id="flight-preview"></div>${state.time===0&&!demo?'<button class="deck-demo" id="start-demo">▷ Watch ORI fly a guided mission <span>~45 seconds · keeps your run</span></button>':''}<button class="deck-abort" id="stop-trial" ${demo?'disabled':''}>Transfer to duty authority ↗</button>`;renderPreview();
 }
 function renderPreview(){let el=$('#flight-preview');if(!el)return;if(!selected){el.innerHTML=`<p class="flight-select-hint">${demo?'ORI will select the next action automatically.':'Select an action to compare its consequences before committing.'}</p>`;return}let f=forecast(c,state,selected),n=f.next;el.innerHTML=`<div class="flight-forecast"><span class="eyebrow">PREDICTED AT T+${n.time}</span><div class="flight-forecast-grid">${Object.keys(RESOURCE_NAMES).map(k=>`<div><label>${RESOURCE_NAMES[k]}</label><b>${state[k].toFixed(1)} <i>→</i> <strong>${n[k].toFixed(1)}</strong><small>${units[k]}</small></b></div>`).join('')}</div><p>${esc(f.choice.delayed?.length?f.choice.delayed.map(e=>'T+'+e.at+': '+e.text).join(' '):f.choice.coaching)}</p><button class="deck-primary" id="commit-decision" ${f.reason?'disabled':''}>Commit & fly to T+${n.time} →</button></div>`;$('#mission-coaching').textContent=guide();}
 function openWork(area='decision'){
 playing=false;if(area==='decision'&&!state.ended){replay=state.time;paintFrame();$('#flight-work').scrollTop=0;$('#flight-work').querySelector('button')?.focus({preventScroll:true});return}
 if(area==='decision')replay=state.time;tab=area;root.querySelectorAll('[data-mission-tab]').forEach(x=>x.classList.toggle('active',x.dataset.missionTab===area));renderWork();paintFrame();$('#mission-console').showModal();$('#mission-console').scrollTop=0;
 }
 function startPlayback(from=replay){replay=from;playing=true;last=0;paintFrame();}
 function primaryAction(){let action=playbackControls(state,replay,playing).action;if(action==='decision')openWork();else if(action==='pause'){playing=false;paintFrame()}else startPlayback(action==='replay'?0:replay);}
 function updateControls(){let v=playbackControls(state,replay,playing);$('#flight-status').textContent=demo?'ORI / GUIDED FLIGHT':v.status;$('#mission-play').textContent=playing?'Ⅱ Pause':state.time===0?'Choose an action →':replay<state.time?'▶ Resume':'↻ Replay';$('#mission-play').setAttribute('aria-label',playing?'Pause flight':state.time===0?'Start mission':replay<state.time?'Resume flight':'Replay committed mission history');}
 function drawTrends(){for(let k of Object.keys(RESOURCE_NAMES)){let series=state.samples.length?state.samples:[snapshot(state)],max=c.initial[k],points=series.map(p=>`${p.time/96*150},${26-Math.min(1,p[k]/max)*22}`).join(' ');$('#spark-'+k).innerHTML=`<defs><clipPath id="clip-${k}"><rect id="clip-window-${k}" width="150" height="30"/></clipPath></defs><line x1="0" x2="150" y1="${26-LIMITS[k]/max*22}" y2="${26-LIMITS[k]/max*22}" stroke="#e4ab6b55" stroke-dasharray="2 3"/><polyline clip-path="url(#clip-${k})" points="${points}" fill="none" stroke="#7cc2b9" stroke-width="1.4"/><line class="spark-cursor" y1="1" y2="28" stroke="#eab879" stroke-width="1"/>`}}
 function commit(id){if(demo)view=['orbit','chase','link','orbit','chase','chase'][state.stage];let start=state.time;state=commitChoice(c,state,id);selected=null;persist();replay=start;last=0;playing=demo||!matchMedia('(prefers-reduced-motion: reduce)').matches;if(!playing)replay=state.time;demoHold=0;render();$('#mission-primary')?.focus({preventScroll:true});}
 function startDemo(){demoSaved=state;demo=true;state=initialMission(c);selected=null;replay=0;playing=false;demoHold=0;speed=3;view='orbit';render();root.scrollIntoView({behavior:'instant',block:'start'});notify('ORI is flying a guided example. Your saved mission is unchanged.')}
 function exitDemo(){state=demoSaved;demoSaved=null;demo=false;selected=null;replay=state.time;playing=false;speed=1;render();}
 function renderWork(){let el=$('#mission-work');if(tab==='evidence'){let visibleEvidence=frameAt(state,replay).evidence;el.innerHTML=`<p class="small muted">Evidence available in the displayed state: T+${replay.toFixed(1)}. Later arrivals stay locked until their mission time.</p><div class="evidence-locker">${c.evidenceCatalog.map(e=>`<article class="evidence-record ${visibleEvidence.includes(e.id)?'obtained':e.id.startsWith('X')?'rejected':'missing'}"><div><span>${e.id}</span><b>${visibleEvidence.includes(e.id)?'IN THIS RUN':e.id.startsWith('X')?'INAPPLICABLE':'NOT YET OBTAINED'}</b></div><h3>${esc(e.title)}</h3><p>${esc(e.scope||e.problem)}</p></article>`).join('')}</div>`;return}
 if(tab==='ledger'){el.innerHTML=`<div class="mission-ledger">${state.history.length?state.history.map((e,i)=>`<details ${i===state.history.length-1?'open':''}><summary><span>T+${e.time}</span><b>${esc(e.label)}</b><i>↗</i></summary><div><p>${esc(e.coaching)}</p><table><thead><tr><th>Resource</th><th>Before</th><th>T+${e.to}</th><th>Net change</th></tr></thead><tbody>${Object.entries(RESOURCE_NAMES).map(([k,n])=>`<tr><td>${n}</td><td>${e.before[k].toFixed(1)}</td><td>${e.after[k].toFixed(1)}</td><td>${(e.after[k]-e.before[k]).toFixed(1)} ${units[k]}</td></tr>`).join('')}</tbody></table><p class="small muted">Net change includes elapsed-time baseline and events, not just the immediate decision cost.</p></div></details>`).join(''):'<div class="empty">Your first commitment will start the ledger.</div>'}<h3 class="ledger-events-title">Events through time</h3>${state.events.map(e=>`<div class="ledger-event"><b>T+${e.time}</b><p>${esc(e.text)}</p></div>`).join('')||'<p class="small muted">Scheduled consequences will appear here when they occur.</p>'}</div>`;return}
 if(tab==='model'){el.innerHTML=`<div class="model-notes"><span class="eyebrow">TRANSPARENT TRAINING MODEL</span><h3>Understand the boundary.</h3><p><b>${esc(c.scenario.name)}</b> — ${esc(c.scenario.brief)}</p><p>${esc(c.disclosure)}</p><p>${esc(c.premise)}</p><table class="source-index"><thead><tr><th>Assumption</th><th>Training value</th></tr></thead><tbody><tr><td>Sunlight / eclipse energy rate</td><td>+${c.baseline.perElapsedMinute.batterySun} / ${c.baseline.perElapsedMinute.batteryEclipse} battery points per minute</td></tr><tr><td>Sunlight / eclipse thermal-margin rate</td><td>−0.025 / +0.04°C per minute</td></tr><tr><td>Eclipse window</td><td>T+32 to T+62; authored scenario timing</td></tr><tr><td>Attention budget</td><td>${c.initial.operatorMinutes} operator minutes; does not replenish with elapsed time</td></tr><tr><td>Training floors</td><td>30% battery · 4°C margin · 8 m/s reserve · 0 operator minutes</td></tr></tbody></table><p>Action costs and queued penalties apply exactly once. The next-state preview includes baseline changes and any events due before the next decision. Playback never changes saved decisions or spends resources again.</p><p>Only the existing human command procedure can execute the contingency manoeuvre. One orbit does not satisfy the Constellation playbook’s full-quarter shadow prerequisite or authorise new autonomous commands.</p><p>The final argument review compares your structured recommendation with this run’s ledger. It does not grade free-text prose quality or issue assurance approval.</p><div class="mission-source-links"><a href="#module/constellation">Constellation / CO1–CO3 ↗</a><a href="#module/earth-observation">Earth observation / EO2–EO3 ↗</a><a href="#module/ground-systems">Ground / GS2–GS4 ↗</a><a href="#module/debris">Orbital safety / CD1–CD4 ↗</a><a href="#module/capstone">Assurance / SC2–SC4 ↗</a></div></div>`;return}
 if(state.ended){el.innerHTML=debrief();if(review)showReview();return}
 let st=c.stages[state.stage];el.innerHTML=`<section class="decision-brief"><span class="eyebrow">DECISION ${state.stage+1} / 6 · T+${state.time} MIN</span><h2>${esc(st.title)}</h2><p>${esc(st.brief)}</p><small>SOURCE LENS: ${esc(st.source)}</small></section><div class="decision-options">${st.choices.map((o,i)=>{let r=availability(c,state,o);return `<button class="decision-choice ${selected===o.id?'selected':''} ${r?'unavailable':''}" data-choice="${o.id}" aria-pressed="${selected===o.id}" ${r?'aria-disabled="true"':''}><span class="choice-index">${String.fromCharCode(65+i)}</span><h3>${esc(o.title)}</h3><p>${esc(r||o.coaching)}</p><div class="choice-costs">${Object.entries(o.effects).filter(([k])=>k in units).map(([k,v])=>`<span>${v>0?'+':''}${v} ${units[k]} ${k==='operatorMinutes'?'attention':k==='thermalMargin'?'margin':k==='deltaV'?'reserve':'battery'}</span>`).join('')||(r?'<span>AUTHORITY BOUNDARY</span>':'<span>NO IMMEDIATE RESOURCE COST</span>')}</div><b>${r?'LOCKED · SEE REQUIREMENT':selected===o.id?'SELECTED FOR PREVIEW':'PREVIEW CONSEQUENCES ↗'}</b></button>`}).join('')}</div><div id="decision-preview"></div><div class="mission-stop"><button class="text-button" id="stop-trial">Stop candidate trial and transfer to duty authority</button><span>Retains the existing mission baseline; records a constrained outcome.</span></div>`;renderPreview()}
 function selectField(id,label,opts){let a=state.arguments||{};return `<div class="form-field"><label for="arg-${id}">${label}</label><select id="arg-${id}" data-argument="${id}"><option value="">Select…</option>${opts.map(([v,t])=>`<option value="${v}" ${String(a[id])===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
 function debrief(){let a=state.arguments||{},o=missionOutcome(state),previous=state.previousRun;return `<section class="mission-outcome ${o.kind}"><span class="eyebrow">MISSION DEBRIEF / ${state.time===96?'ORBIT COMPLETE':'TRIAL STOPPED'}</span><h2>${o.title}</h2><p><b>${esc(c.scenario.name)}</b> — ${esc(c.scenario.lesson)}</p><p>${state.flags.includes('limitedContinuation')?'The record supports only the scope explicitly earned. No autonomous commanding or fleet transfer has been authorised.':'Holding a release preserves the existing mission baseline. It does not claim that unresolved events are closed.'}</p>${previous?`<div class="run-comparison"><b>Compared with ${esc(scenarioFor(previous.scenarioId).name)}</b><small>Resource differences include starting conditions and selected actions.</small>${Object.keys(RESOURCE_NAMES).map(k=>`<span>${RESOURCE_NAMES[k]}: ${(state[k]-previous[k]).toFixed(1)} ${units[k]}</span>`).join('')}</div>`:''}</section><div class="argument-layout"><section class="panel"><span class="eyebrow">DEFEND THE RECOMMENDATION</span><h3 style="margin-top:10px">Tie your claim to this mission’s record.</h3>${selectField('recommendation','What are you recommending?',[['continue','One-spacecraft advisory continuation'],['hold','Hold candidate release; keep the baseline'],['fleet','Fleet-wide autonomous release']])}<fieldset class="argument-evidence"><legend>Which records support your claim?</legend>${c.evidenceCatalog.map(e=>`<label><input type="checkbox" data-argument-evidence="${e.id}" ${(a.evidence||[]).includes(e.id)?'checked':''}><span><b>${e.id}</b> ${esc(e.title)}<small>${state.evidence.includes(e.id)?'Obtained in this run':e.id.startsWith('X')?'Inapplicable':'Not obtained'}</small></span></label>`).join('')}</fieldset><div class="argument-pair">${selectField('tradeoff','Which resource trade-off do you claim?',Object.entries(RESOURCE_NAMES))}${selectField('event','Which decision caused it?',state.history.map((h,i)=>[String(i),'T+'+h.time+' · '+h.label]))}</div><div class="argument-pair">${selectField('stopMetric','Stop if this resource falls below…',Object.entries(RESOURCE_NAMES))}<div class="form-field"><label for="arg-threshold">Threshold in the metric’s units</label><input id="arg-threshold" data-argument="threshold" type="number" step="0.1" value="${esc(a.threshold||'')}" placeholder="For example, 35 for battery %"></div></div>${selectField('owner','Who owns the stop and unresolved obligations?',[['flight','Duty flight director'],['vendor','Planner vendor'],['model','The planning model']])}${selectField('next','What is the next material evidence task?',[['conjunction','Close or explicitly reassign the unresolved conjunction record'],['handover','Complete and independently challenge the integrated handover pack'],['shadow','Establish current-build shadow evidence'],['transfer','Run longer-duration shadow evaluation and separate transfer assessment']])}${selectField('expiry','When does this claim expire?',[['nextpass','Before the next pass; reopen on build or regime change'],['never','Keep it valid indefinitely']])}<div class="form-field"><label for="arg-rationale">Your recommendation, evidence and trade-offs</label><textarea id="arg-rationale" data-argument="rationale" placeholder="Explain why your chosen scope is justified, what you gave up, and what remains unresolved. This prose is for human review.">${esc(a.rationale||'')}</textarea></div><div class="filter-row"><button id="review-argument" class="button primary">Challenge my argument ↗</button><button id="export-argument" class="button subtle">Export board brief ↓</button></div></section><aside class="argument-review"><div class="ori-sprite thinking" role="img" aria-label="ORI considering your argument"></div><span class="eyebrow">EVIDENCE-TO-CLAIM REVIEW</span><h3>Does your claim survive the record?</h3><p>Each check quotes the actual evidence or consequence that supports or contradicts your selection.</p><div id="argument-review-results"><p class="small muted">Complete your structured argument, then run the challenge. Arbitrary prose is not scored by character count or keywords.</p></div></aside></div>`}
 function showReview(){let el=$('#argument-review-results');if(!el)return;el.innerHTML=`<div class="review-counts">${['supported','contradicted','missing'].map(k=>`<span class="${k}"><b>${review.filter(r=>r.status===k).length}</b> ${k}</span>`).join('')}</div>${review.map(r=>`<div class="argument-check ${r.status}"><b>${r.status==='supported'?'✓':r.status==='contradicted'?'×':'○'} ${r.title}</b><p>${esc(r.detail)}</p></div>`).join('')}<p class="small muted">Free-text reasoning still needs independent human assessment.</p>`;$('.argument-review .ori-sprite').className='ori-sprite '+(review.every(r=>r.status==='supported')?'pleased':'alert')}
 function paintFrame(){if(!$('#mission-time'))return;let f=frameAt(state,replay),n=flightNarrative(f);$('#mission-time').value=replay;$('#mission-time').style.setProperty('--recorded',state.time/96*100+'%');$('#mission-clock').textContent=clock(replay)+' / 96:00';$('#scene-time').textContent='T+'+clock(replay);$('#scene-phase').textContent=n.phase;$('#scene-headline').textContent=n.title;$('#scene-detail').textContent=n.detail;$('#mission-mode').textContent=playing?'FLIGHT IN PROGRESS':replay<state.time?'REPLAY PAUSED':state.ended?'FINAL RECORD':'DECISION HOLD';$('#mission-data-value').textContent=f.dataValue;$('#deck-evidence-count').textContent=f.evidence.length;if(replay<state.time){let arrived=state.events.filter(e=>e.time<=replay).at(-1);$('#mission-coaching').textContent=arrived&&arrived.time>=replay-5?arrived.text:n.detail;$('#ori-mission .ori-sprite').className='ori-sprite '+(!f.groundContact?'alert':'thinking')}else if(!selected){$('#mission-coaching').textContent=guide();$('#ori-mission .ori-sprite').className='ori-sprite '+mood()}$('#mission-contact').textContent=f.groundContact?'Acquired':'Lost';$('#contact-led').classList.toggle('offline',!f.groundContact);$('#mission-release').textContent=f.flags.includes('releaseHeld')?'Held':f.flags.includes('limitedContinuation')?'Limited continuation':'One spacecraft';$('#deck-time-fill').style.width=replay/96*100+'%';for(let k of Object.keys(RESOURCE_NAMES)){$('#mm-'+k).textContent=f[k].toFixed(1);$('#meter-'+k).style.width=Math.max(0,Math.min(100,f[k]/c.initial[k]*100))+'%';$('#meter-'+k).classList.toggle('low',f[k]<LIMITS[k]+(k==='battery'?15:k==='operatorMinutes'?10:3));$('#clip-window-'+k).setAttribute('width',replay/96*150);$('#spark-'+k+' .spark-cursor').setAttribute('x1',replay/96*150);$('#spark-'+k+' .spark-cursor').setAttribute('x2',replay/96*150)}let key=[state.stage,playing,replay<state.time,n.phase,n.title,demo].join();if(key!==consoleKey){consoleKey=key;let focusId=document.activeElement?.id;renderFlight();$('#flight-work').scrollTop=0;if(focusId==='mission-primary')$('#mission-primary')?.focus({preventScroll:true})}let ck=[playing,replay<state.time,state.stage,demo].join();if(ck!==controlKey){controlKey=ck;updateControls()} }
 const events=[];function on(el,ev,fn){el.addEventListener(ev,fn);events.push(()=>el.removeEventListener(ev,fn))}
 on(root,'click',e=>{let b=e.target.closest('button');if(!b)return;
 if(b.id==='start-demo'||b.hasAttribute('data-start-demo')){startDemo();return}
 if(b.id==='exit-demo'||b.hasAttribute('data-exit-demo')){exitDemo();return}
 if(b.dataset.seek!==undefined){replay=Math.min(state.time,Number(b.dataset.seek));playing=false;paintFrame();return}
 if(b.id==='mission-primary'){primaryAction();return}
 if(b.id==='mission-open-decision'){openWork();return}
 if(b.dataset.openWork){openWork(b.dataset.openWork);return}
 if(b.id==='close-mission-console'){$('#mission-console').close();return}
 if(b.dataset.choice){if(demo)return;let o=c.stages[state.stage].choices.find(o=>o.id===b.dataset.choice),reason=availability(c,state,o);if(reason){notify(reason);$('#mission-coaching').textContent=reason;$('#ori-mission .ori-sprite').className='ori-sprite alert';return}selected=b.dataset.choice;renderFlight();root.querySelector('[data-choice="'+selected+'"]').focus({preventScroll:true});$('#flight-preview').scrollIntoView({behavior:'instant',block:'nearest'});return}
 if(b.id==='commit-decision'&&selected){try{commit(selected);$('#flight-work').scrollTop=0;notify('Commitment recorded. Flying to T+'+state.time+'.')}catch(err){notify(err.message)}}
 if(b.id==='stop-trial'){state=emergencyHandover(c,state);selected=null;playing=false;replay=state.time;persist();render()}
 if(b.dataset.missionTab){if(b.dataset.missionTab==='decision'&&!state.ended)$('#mission-console').close();openWork(b.dataset.missionTab)}
 if(b.id==='mission-play'){if(state.time===0)openWork();else if(playing){playing=false;paintFrame()}else startPlayback(replay>=state.time?0:replay)}
 if(b.id==='mission-live'){playing=false;replay=state.time;paintFrame()}
 if(b.dataset.zoom){scene.zoomBy(Number(b.dataset.zoom));return}if(b.id==='camera-reset'){scene.view(view);$('#explode-vehicle').setAttribute('aria-pressed','false');$('#explode-vehicle').textContent='Inspect +';return}
 if(b.dataset.vehicle){view=b.dataset.vehicle;scene.view(view);root.querySelectorAll('[data-vehicle]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#explode-vehicle').setAttribute('aria-pressed','false');$('#explode-vehicle').textContent='Inspect +'}
 if(b.id==='explode-vehicle'){let v=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(v));b.textContent=v?'Assemble −':'Inspect +';view='chase';root.querySelectorAll('[data-vehicle]').forEach(x=>{x.classList.toggle('active',x.dataset.vehicle==='chase');x.setAttribute('aria-pressed',String(x.dataset.vehicle==='chase'))});scene.explode(v)}
 if(b.id==='minimise-mission-ori'){let v=$('#ori-mission').classList.toggle('compact');b.textContent=v?'+':'−';b.setAttribute('aria-label',v?'Expand ORI’s coaching':'Minimise ORI’s coaching')}
 if(b.dataset.scenario){nextScenario=b.dataset.scenario;root.querySelectorAll('[data-scenario]').forEach(x=>{let active=x.dataset.scenario===nextScenario;x.classList.toggle('selected',active);x.setAttribute('aria-pressed',String(active))});return}
 if(b.id==='mission-restart'||b.hasAttribute('data-restart'))$('#restart-dialog').showModal();if(b.id==='cancel-restart')$('#restart-dialog').close();if(b.id==='confirm-restart'){let old={...snapshot(state),scenarioId:state.scenarioId||'standard'};c=scenarioCase(baseCase,nextScenario);state=initialMission(c);state.previousRun=old;selected=null;replay=0;playing=false;review=null;tab='decision';persist();render();root.scrollIntoView({behavior:'instant',block:'start'})}
 if(b.id==='review-argument'){review=reviewArgument(state,state.arguments);showReview();$('#argument-review-results').scrollIntoView({behavior:'smooth',block:'center'})}
 if(b.id==='export-argument')exportBrief();
 });
 on(document,'visibilitychange',()=>{last=0});
 on(root,'input',e=>{let x=e.target;if(x.id==='mission-speed'){speed=Number(x.value);last=0}if(x.id==='mission-time'){playing=false;replay=Math.min(state.time,+x.value);paintFrame()}if(x.dataset.argument){state.arguments[x.dataset.argument]=x.value;review=null;persist();let el=$('#argument-review-results');if(el)el.innerHTML='<p class="small muted">Argument changed. Run the challenge again.</p>'}});
 on(root,'change',e=>{if(e.target.dataset.argumentEvidence){state.arguments.evidence=[...root.querySelectorAll('[data-argument-evidence]:checked')].map(x=>x.dataset.argumentEvidence);review=null;persist();$('#argument-review-results').innerHTML='<p class="small muted">Evidence selection changed. Run the challenge again.</p>'}});
 function saveFile(name,content,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
 on($('#mission-expand'),'click',()=>{let expanded=document.body.classList.toggle('mission-immersive');$('#mission-expand').setAttribute('aria-pressed',String(expanded));$('#mission-expand').textContent=expanded?'⛶ Exit expanded view':'⛶ Expand flight deck'});
 on($('#mission-export'),'click',()=>saveFile('orbital-atlas-mission-record.json',JSON.stringify({exportedAt:new Date().toISOString(),disclosure:c.disclosure,...state},null,2),'application/json'));
 function exportBrief(){let a=state.arguments,r=reviewArgument(state,a);saveFile('orbital-atlas-mission-board-brief.md',`# ATLAS R8.1 — Mission Board Brief\n\n${c.disclosure}\n\n## Recorded outcome\n${c.scenario.name} — ${missionOutcome(state).title}; T+${state.time} minutes\n\n## Final resource state\n${Object.keys(RESOURCE_NAMES).map(k=>`- ${RESOURCE_NAMES[k]}: ${state[k].toFixed(1)} ${units[k]}`).join('\n')}\n\n## Structured argument\n${Object.entries(a).filter(([k])=>k!=='rationale').map(([k,v])=>`- ${k}: ${Array.isArray(v)?v.join(', '):v}`).join('\n')}\n\n## Recommendation and trade-offs\n${a.rationale||'Not yet drafted.'}\n\n## Evidence-to-claim challenge\n${r.map(x=>`### ${x.status.toUpperCase()} — ${x.title}\n${x.detail}`).join('\n\n')}\n\n## Decisions\n${state.history.map(x=>`- T+${x.time}: ${x.label}. ${x.coaching}`).join('\n')}\n\nFree-text reasoning requires independent human assessment.`, 'text/markdown')}
 render();function tick(now){if(disposed)return;raf=requestAnimationFrame(tick);let dt=last?Math.max(0,(now-last)/1000):0;last=now;if(playing&&!document.hidden){replay=advancePlayback(replay,state.time,dt,speed);if(replay>=state.time)playing=false;paintFrame()}else if(demo&&!state.ended&&replay>=state.time&&!document.hidden&&!$('#mission-console').open){demoHold+=dt;if(demoHold>2.5)commit(c.scenario.route[state.stage])}}raf=requestAnimationFrame(tick);return ()=>{document.body.classList.remove('mission-page','mission-immersive');disposed=true;cancelAnimationFrame(raf);scene?.dispose();events.forEach(f=>f())};
}
